'use strict';
const $=s=>document.querySelector(s);let data={},toastTimer;let selectedDate='';let displayedToday='';
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500)}
function ukDate(now=new Date()){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')}
function ukMinutes(){let p=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date());return Number(p.find(x=>x.type==='hour').value)*60+Number(p.find(x=>x.type==='minute').value)+Number(p.find(x=>x.type==='second').value)/60}
const mins=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
const clock=t=>{let [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`};
const names=['Fajr','Zuhr','Asr','Maghrib','Isha'];
function getRow(date){return data[date.slice(0,7)]?.rows.find(r=>r.date===date)}
function nextEvent(row,date){const today=date===ukDate(),now=ukMinutes();let ev=row.jamaat.map((t,i)=>({name:names[i],time:t,min:mins(t)}));if(row.day==='Fri')ev.push({name:'Jumu’ah',time:row.jumuah,min:mins(row.jumuah)});return ev.sort((a,b)=>a.min-b.min).find(e=>!today||e.min>now)}
function renderDaily(){const date=selectedDate,row=getRow(date);$('#today-label').textContent=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/London'}).format(new Date(date+'T12:00:00Z'));if(!row){$('#prayer-times').innerHTML='<p class="small">The masjid timetable for this date has not yet been provided. Please contact the committee for prayer times.</p>';$('#sunrise').textContent='';$('#jumuah').textContent='';return}const next=nextEvent(row,date);$('#prayer-times').innerHTML=`<table class="prayer-table"><thead><tr><th scope="col">PRAYER</th><th scope="col">BEGINS</th><th scope="col">JAMAAT</th></tr></thead><tbody>${names.map((n,i)=>`<tr class="${date===ukDate()&&next?.name===n?'upcoming':''}"><td>${n}</td><td>${clock(row.begin[i])}</td><td>${clock(row.jamaat[i])}</td></tr>`).join('')}</tbody></table>`;$('#sunrise').textContent='Sunrise '+clock(row.sunrise);$('#jumuah').textContent='Jumu’ah '+clock(row.jumuah)}
function renderNext(){if(!$('#next-name'))return;const today=ukDate(),row=getRow(today);if(!row){$('#next-name').textContent='Timetable coming soon';$('#countdown').textContent='Please contact the masjid for current prayer times.';return}let next=nextEvent(row,today);if(next){const d=Math.ceil(next.min-ukMinutes());$('#next-name').textContent=next.name+' · '+clock(next.time);$('#countdown').textContent=d>=60?`In ${Math.floor(d/60)}h ${d%60}m`:`In ${d} minutes`}else{const tomorrow=new Date(today+'T12:00:00Z');tomorrow.setUTCDate(tomorrow.getUTCDate()+1);const nextRow=getRow(tomorrow.toISOString().slice(0,10));$('#next-name').textContent=nextRow?'Fajr · '+clock(nextRow.jamaat[0]):'Today’s jamaats have finished';$('#countdown').textContent=nextRow?'Tomorrow morning':'Next timetable coming soon'}}
function renderMonth(){const key=$('#month-select').value,item=data[key];$('#download-pdf').href=item.pdf;$('#download-pdf').setAttribute('download',`Baitul-Aman-${key}.pdf`);$('#monthly-table').innerHTML=`<caption class="sr-only">${item.name} prayer timetable, UK local time, 24-hour format</caption><thead><tr><th colspan="2">${item.name}</th><th colspan="5">JAMAAT TIMES</th><th colspan="6">BEGINNING TIMES</th><th>FRIDAY</th></tr><tr>${['Date','Day',...names,'Fajr','Sunrise','Zuhr','Asr','Maghrib','Isha','Jumu’ah'].map(n=>`<th scope="col">${n}</th>`).join('')}</tr></thead><tbody>${item.rows.map(r=>`<tr class="${r.date===ukDate()?'today':''}">${[Number(r.date.slice(-2)),r.day,...r.jamaat,r.begin[0],r.sunrise,...r.begin.slice(1),r.day==='Fri'?r.jumuah:'—'].map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody>`}
$('#year').textContent=new Date().getFullYear();
$('.menu-button').addEventListener('click',()=>{let expanded=$('.menu-button').getAttribute('aria-expanded')==='true';$('.menu-button').setAttribute('aria-expanded',String(!expanded));$('#navigation').classList.toggle('open',!expanded)});
document.querySelectorAll('.copy-button').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Copied to clipboard')}catch{toast('Please select and copy the bank details manually.')}}));
document.querySelectorAll('.amount-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.amount-button').forEach(a=>a.setAttribute('aria-pressed',String(a===b)));$('#donation-status').textContent=`£${b.dataset.amount} selected. Coming Soon — online donations are not yet available.`}));
if($('#view-poster')){$('#view-poster').addEventListener('click',()=>$('#poster-dialog').showModal());$('.dialog-close').addEventListener('click',()=>$('#poster-dialog').close());$('#poster-dialog').addEventListener('click',e=>{if(e.target===$('#poster-dialog'))$('#poster-dialog').close()})}
if(location.hash.startsWith('#service-')){const d=$(location.hash);if(d)d.open=true}
if($('#prayer-times'))fetch('prayer-data.json').then(r=>{if(!r.ok)throw Error('Unable to load');return r.json()}).then(d=>{data=d;selectedDate=ukDate();displayedToday=selectedDate;$('#prayer-date').value=selectedDate;renderDaily();renderNext();$('#prayer-date').addEventListener('change',e=>{if(e.target.value){selectedDate=e.target.value;renderDaily()}});if($('#month-select')){let keys=Object.keys(data).sort();$('#month-select').innerHTML=keys.map(k=>`<option value="${k}">${data[k].name}</option>`).join('');$('#month-select').value=data[ukDate().slice(0,7)]?ukDate().slice(0,7):keys.at(-1);renderMonth();$('#month-select').addEventListener('change',renderMonth)}setInterval(()=>{const today=ukDate();if(today!==displayedToday){if(selectedDate===displayedToday){selectedDate=today;$('#prayer-date').value=today;}displayedToday=today;}if(selectedDate===today)renderDaily();renderNext()},30000)}).catch(()=>{$('#prayer-times').textContent='Prayer times could not be loaded. Please try again or download a monthly timetable.';$('#today-label').textContent='Timetable unavailable';if($('#next-name'))$('#next-name').textContent='Timetable unavailable'});

if($('#photo-viewer')){
 const viewer=$('#photo-viewer'),photos=[...document.querySelectorAll('.photo-open')];let current=0,opener;
 function showPhoto(index){current=index;const photo=photos[current];$('#viewer-image').src=photo.href;$('#viewer-image').alt=photo.dataset.caption;$('#viewer-caption').textContent=photo.dataset.caption;$('#photo-counter').textContent=`${current+1} / ${photos.length}`;$('#photo-original').href=photo.href;$('#photo-prev').disabled=current===0;$('#photo-next').disabled=current===photos.length-1;}
 photos.forEach((photo,index)=>photo.addEventListener('click',event=>{event.preventDefault();opener=photo;showPhoto(index);viewer.showModal();$('#photo-close').focus();}));
 $('#photo-close').addEventListener('click',()=>viewer.close());$('#photo-prev').addEventListener('click',()=>{if(current>0)showPhoto(current-1)});$('#photo-next').addEventListener('click',()=>{if(current<photos.length-1)showPhoto(current+1)});
 viewer.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'&&current>0){event.preventDefault();showPhoto(current-1)}if(event.key==='ArrowRight'&&current<photos.length-1){event.preventDefault();showPhoto(current+1)}});viewer.addEventListener('click',event=>{if(event.target===viewer){const r=viewer.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)viewer.close()}});viewer.addEventListener('close',()=>opener?.focus());
}

// Repeating reels: automatic playback, manual browsing and accessible pause.
document.querySelectorAll('.photo-reel').forEach(reel=>{
 const slides=[...reel.querySelectorAll('.reel-slide')],track=reel.querySelector('.reel-track');let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function render(){track.style.transform=`translateX(-${index*100}%)`;reel.querySelector('.reel-count').textContent=`${index+1} / ${slides.length}`;slides.forEach((slide,i)=>{slide.setAttribute('aria-hidden',String(i!==index));slide.inert=i!==index;});}
 function move(delta){index=(index+delta+slides.length)%slides.length;render();}
 reel.querySelector('.reel-prev').addEventListener('click',()=>move(-1));reel.querySelector('.reel-next').addEventListener('click',()=>move(1));
 setInterval(()=>{if(!paused&&!document.hidden&&!document.querySelector('#photo-viewer[open]')&&!reel.matches(':hover')&&!reel.contains(document.activeElement))move(1)},Number(reel.dataset.interval));render();
 if(slides.length===1)reel.querySelector('.reel-controls').hidden=true;
});
